function wave(g,x0,y0,x1,y1,a,l,c){const d=Math.hypot(x1-x0,y1-y0);if(d<2)return;const ux=(x1-x0)/d,uy=(y1-y0)/d;g.beginPath();for(let s=0;s<=d;s+=2){const o=a*Math.sin(s/l*TAU);g.lineTo(x0+ux*s-uy*o,y0+uy*s+ux*o)}g.strokeStyle=c;g.lineWidth=2.5;g.stroke()}
