const mk=(col,r)=>new THREE.Mesh(new THREE.SphereGeometry(r,20,20),new THREE.MeshStandardMaterial({color:col,emissive:col,emissiveIntensity:.5,roughness:.4}));
for(let i=0;i<8;i++){const m=mk(i%2?0xff4d7d:0x4da3ff,.32);m.position.set(Math.sin(i*2.4)*.35,Math.cos(i*1.7)*.35,Math.sin(i*3.1)*.35);G.add(m)}
const pl=new THREE.PointLight(0xffffff,1.4,50);pl.position.z=8;S.add(pl);S.add(new THREE.AmbientLight(0x8866ff,.6));
const el=[];
for(let i=0;i<3;i++){const o=new THREE.Group();o.rotation.set(i*1.05,i*.6,i);const p=[];for(let k=0;k<=96;k++){const t=k/96*TAU;p.push(new THREE.Vector3(Math.cos(t)*3,Math.sin(t)*1.7,0))}
o.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(p),new THREE.LineBasicMaterial({color:0xa46bff,transparent:true,opacity:.6})));
const e=mk(0x47d7ff,.15);o.add(e);G.add(o);el.push(e)}
const sp=[];for(let i=0;i<900;i++)sp.push((Math.random()-.5)*60,(Math.random()-.5)*40,-Math.random()*30);
const sg=new THREE.BufferGeometry();sg.setAttribute("position",new THREE.Float32BufferAttribute(sp,3));S.add(new THREE.Points(sg,new THREE.PointsMaterial({color:0xffffff,size:.07})));
let t=0,k=1,mx=0,my=0;addEventListener("pointermove",e=>{mx=e.clientX/innerWidth-.5;my=e.clientY/innerHeight-.5});
