g.setLineDash([4,5]);g.strokeStyle="rgba(255,255,255,.3)";g.beginPath();g.moveTo(cx-300,cy);g.lineTo(cx+300,cy);g.stroke();g.beginPath();g.moveTo(cx,cy);g.lineTo(cx+dx*200,cy+dy*200);g.moveTo(cx,cy);g.lineTo(cx+ex*200,cy+ey*200);g.stroke();g.setLineDash([]);
g.strokeStyle="#ffd54a";g.beginPath();g.arc(cx,cy,60,0,q.th);g.stroke();txt(g,"θ",cx+66,cy+18,"#ffd54a");
if(ph==0){wave(g,30,cy,cx-12,cy,6,16,"rgba(255,213,74,.5)");txt(g,"photon incident",30,cy-20,"#ffd54a")}
if(ph==1){const hx=30+(cx-30-12)*t;wave(g,Math.max(30,hx-110),cy,hx,cy,6,16,"#ffd54a");t+=.015;if(t>=1){ph=2;t=0}}
